import SwiftUI
import Foundation
import MapLibre

/// The P3 map styles: Standard and Outdoor by day and night, Satellite by day only (App/Resources/MapStyle, generated by tools/stylegen from design/p3v3).
enum MapStyleKind: String, CaseIterable, Sendable {
    case standard, outdoor, satellite

    init(_ style: MapStyleSheet.Style) {
        switch style {
        case .standard: self = .standard
        case .outdoor: self = .outdoor
        case .satellite: self = .satellite
        }
    }
}

enum MapMode: String, CaseIterable, Sendable {
    case day, night

    /// The map's light or dark style: the phone's appearance unless the rider picked one (Map sheet, 30 Oct).
    init(_ scheme: ColorScheme, _ appearance: MapAppearance) {
        switch appearance {
        case .auto: self = scheme == .dark ? .night : .day
        case .light: self = .day
        case .dark: self = .night
        }
    }
}

/// Map sheet → Light / Dark / Auto (follows the phone).
enum MapAppearance: String, CaseIterable, Codable, Sendable {
    case auto, light, dark
    var title: String { switch self { case .auto: "Auto"; case .light: "Light"; case .dark: "Dark" } }
}

private struct MapAppearanceKey: EnvironmentKey { static let defaultValue = MapAppearance.auto }
extension EnvironmentValues {
    /// Set at the root from ``AppState/mapAppearance``; every map reads it.
    var mapAppearance: MapAppearance {
        get { self[MapAppearanceKey.self] }
        set { self[MapAppearanceKey.self] = newValue }
    }
}

enum VelixMapStyle {
    enum Failure: Error { case missingStyle(String) }

    /// OpenFreeMap's OpenMapTiles TileJSON: the basemap where no installed pack has tiles (``PackTileProtocol``).
    static let onlineBasemap = "https://tiles.openfreemap.org/planet"

    /// The bundled style JSON. Its sources are served by ``PackTileProtocol`` from every installed pack (OpenFreeMap
    /// outside them). Glyphs load from the bundle (`asset://MapStyle/glyphs`); images come from ``MapImages``.
    static func url(_ kind: MapStyleKind, _ mode: MapMode) throws -> URL {
        // Satellite has the one (day) style, whatever the appearance (Filippo, 7 Nov).
        let name = "\(kind.rawValue)-\(kind == .satellite ? MapMode.day.rawValue : mode.rawValue)"
        guard let src = Bundle.main.url(forResource: name, withExtension: "json", subdirectory: "MapStyle") else {
            throw Failure.missingStyle(name)
        }
        return src
    }

    /// Place and water labels (tools/stylegen: `PLACE_NAME`), named in the phone's language.
    static let placeLabelPrefixes = ["label-country", "label-region", "label-city", "label-town", "label-village", "label-water"]

    /// A place's name in `language` (Filippo, 6 Nov: the phone's), else in Latin letters, else as written locally.
    /// Languages in other scripts get the Latin letters only: the map's glyphs are Atkinson Hyperlegible (Latin).
    static func placeName(language: String?) -> [Any] {
        let latin: [Any] = ["get", "name:latin"], local: [Any] = ["get", "name"]
        guard let id = language else { return ["coalesce", latin, local] }
        let lang = Locale.Language(identifier: id)
        guard let code = lang.languageCode?.identifier, lang.maximalIdentifier.contains("-Latn") else {
            return ["coalesce", latin, local]
        }
        return ["coalesce", ["get", "name:\(code)"], latin, local]
    }

    /// Name the place labels of a freshly loaded style in the phone's language.
    @MainActor
    static func localize(_ style: MLNStyle, language: String? = Locale.preferredLanguages.first) {
        let text = NSExpression(mglJSONObject: placeName(language: language))
        for layer in style.layers where placeLabelPrefixes.contains(where: layer.identifier.hasPrefix) {
            (layer as? MLNSymbolStyleLayer)?.text = text
        }
    }

    /// Layers the MapStyleSheet overlay toggles switch (on / off variants share an id prefix).
    static func visibility(bikeLanes: Bool, transitLines: Bool, layerIDs: [String]) -> [String: Bool] {
        var out: [String: Bool] = [:]
        for id in layerIDs {
            if id.hasPrefix("overlay-cycle-") || id.hasPrefix("eurovelo-") { out[id] = bikeLanes }
            else if id.hasPrefix("overlay-train") || id.hasPrefix("overlay-metro") || id == "overlay-station-metro" { out[id] = transitLines }
            else if id == "station-metro" { out[id] = !transitLines }
        }
        return out
    }
}
